class HashRing {
  constructor(nodes) {
    this.points = [];                 // sorted {hash, node}
    for (const node of nodes) {
      const h = hash32(node);          // one point per physical node
      this.points.push({ hash: h, node });
    }
    this.points.sort((a, b) => a.hash - b.hash);
  }

  getNode(key) {
    const h = hash32(key);
    // linear scan for the first point with hash >= h
    for (let i = 0; i < this.points.length; i++) {
      if (this.points[i].hash >= h) return this.points[i].node;
    }
    return undefined;                  // key hashed past the last point
  }
}
